from pathlib import Path
from repo_workflow.command_grammar import CommandGrammarError, Context, parse_tokens
from repo_workflow.public_commands import COMMANDS
ctx = Context(Path('.'), legal_only=False)
for words in (['start', '235'], ['pause'], ['abort'], ['done']):
  assert parse_tokens(COMMANDS, ctx, words) == tuple(words)
try:
  parse_tokens(COMMANDS, ctx, ['issue', 'start', '235'])
except CommandGrammarError:
  pass
else:
  raise AssertionError('legacy issue start grammar is still public')
